(()=>{const guide=document.querySelector('#explore-guide');let offered=false;const open=()=>{if(!guide.open)guide.showModal()},offer=()=>{if(offered)return;offered=true;open()};window.addEventListener('entrance-start',()=>{offered=false});window.addEventListener('entrance-guide-ready',offer);window.addEventListener('entrance-complete',offer);document.querySelector('#guide-reopen').onclick=open;guide.addEventListener('close',()=>document.querySelector('#map').focus({preventScroll:true}))})();